import java.util.*;
import java.math.BigInteger;

public class Main {
    static long modExp(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int MO = sc.nextInt();

        if (n % 2 != 0) {
            System.out.println(modExp(k, n, MO));
            return;
        }

        long[] fact = new long[n + 1];
        long[] inv_fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MO;
        }

        inv_fact[n] = modExp(fact[n], MO - 2, MO);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MO;
        }

        int t = n;
        List<Integer> bits = new ArrayList<>();
        for (int i = 0; i <= 20; i++) {
            if ((t & 1) != 0) {
                bits.add(1 << i);
            }
            t >>= 1;
        }

        int size = 1 << bits.size();
        int[] S = new int[size];
        for (int mask = 0; mask < size; mask++) {
            int sum = 0;
            for (int j = 0; j < bits.size(); j++) {
                if (((mask >> j) & 1) != 0) {
                    sum += bits.get(j);
                }
            }
            S[mask] = sum;
        }

        int[] p = new int[size];
        for (int i = 0; i < size; i++) {
            int t_idx = -1;
            for (int j = 0; j <= 20; j++) {
                if (((i >> j) & 1) != 0) {
                    t_idx = j;
                }
            }
            p[i] = (1 << (t_idx + 1)) + i;
        }

        long[][] f = new long[k + 1][size];
        f[0][0] = 1;

        for (int i = 0; i < k; i++) {
            for (int j = 0; j < size; j++) {
                if (f[i][j] != 0) {
                    for (int k_idx = p[j]; k_idx < size; k_idx = (k_idx + 1) | j) {
                        int diff = S[k_idx ^ j];
                        long inv_val = inv_fact[diff];
                        f[i + 1][k_idx] = (f[i + 1][k_idx] + f[i][j] * inv_val) % MO;
                        if (k_idx == size - 1) break; // prevent infinite loop
                    }
                }
            }
        }

        long total_pow = modExp(k, n, MO);
        long total_ans = 0;
        for (int i = 0; i <= k; i++) {
            long comb = (((fact[k] * inv_fact[i]) % MO) * inv_fact[k - i]) % MO;
            total_ans = (total_ans + f[i][size - 1] * comb) % MO;
        }

        long final_result = (total_pow - total_ans + MO) % MO;
        System.out.println(final_result);
        sc.close();
    }
}
